// ---- Literal aliases ----
export type ArmState = 'idle' | 'connected' | 'kitted' | 'lobby' | 'armed' | 'live';
/** The MC session's own phase vocabulary. The SERVER owns it: `state.py PHASES = get_args(Phase)` is the
 *  tuple every phase guard tests against, and the console's `Phase` is generated from this alias, so a new
 *  phase cannot reach one side without the other. */
export type Phase = 'muster' | 'build' | 'kit' | 'lobby' | 'armed' | 'live' | 'recap';
/** Respawn profiles (Tony, 2026-09-19). A TIMED respawn (in place, `type` "auto") and a
 *  STATION respawn (a revive at a respawn station) protect and arm differently. docs/spec/contracts.md §3.
 *  timed: seconds of `$TMP` t8 = -100 after `$SPAWN`; 0 = no `$TMP` at all */
export type TimedProtectS = 0 | 1 | 2;
/** timed: the trigger stays held (`$BMAP,0,98`) this long after `$SPAWN` */
export type WeaponDelayMs = 500 | 1000 | 1500 | 3000;
/** station: seconds of t8 = -100; the trigger is live at once */
export type StationProtectS = 0 | 2 | 3;
export type WinBy = 'kills' | 'survival' | 'objective';
/** Tony 2026-09-19 (FOLLOWUPS S45, weapon-design.md §7.3): the three named starting-pool presets, plus
 *  "custom" for a hand-edited pool. Mirrors `LoadoutPreset` -- a label RE-DERIVED from the numbers
 *  (`compile.resolve_health_preset`), never trusted on its own; see that function's docstring. */
export type HealthPreset = 'standard' | 'shields' | 'hardcore' | 'custom';
/** `policy.CHOICES` -- who fills a slot. `policy._check_rule` refuses anything else (and refuses "off"
 *  for the primary: a player with no primary weapon has nothing to play with). */
export type SlotChoice = 'player' | 'host' | 'fixed' | 'off';
/** `policy.PRIMARY_KINDS` / `SEC_KINDS` / `PERK_KINDS` together. A POLICY kind, never a request kind: a
 *  pistol is a "weapon" on the wire, and "sidearm" (A12) narrows a weapon slot to the sidearm-tagged rows. */
export type ItemKind = 'weapon' | 'perk' | 'sidearm';
/** `policy.PRESET_NAMES` -- the named rulesets, plus "custom" for a hand-edited one. */
export type LoadoutPreset = 'open' | 'no_heavies' | 'snipers' | 'custom';
export type PoolEmptyCode = 'off' | 'fixed_missing' | 'only_ids_missing' | 'needs_secondary' | 'unplayable' | 'filtered';
/** A13 / spec/utility.md §5: what a utility phone can be. Mirrors `KIND` in `app/src/beacon.js` (the advert
 *  byte 8) and `KIND_LABEL` in `app/src/utility.js`; a `station_config` naming anything else is refused at PUT. */
export type StationKind = 'respawn' | 'powerup' | 'extraction' | 'bomb' | 'control';
/** A67 (F365): a station's advert strength and where its range value came from. "station" = the operator's long-hold
 *  edit on the station itself; "mc" = the value MC sent in `station_config`. */
export type TxPower = 'ultra_low' | 'low' | 'medium' | 'high';
export type RangeSrc = 'station' | 'mc';
export type RangeField = 'threshold' | 'tx_power';
export type StationItemKind = 'weapon' | 'overshield';
export type PieceKind = 'mode' | 'life' | 'spawn' | 'primary' | 'secondary' | 'perks' | 'misc_loadouts' | 'gameplay';
/** F413: the four native $TID teams (0-3) */
export type TeamColour = 'red' | 'blue' | 'yellow' | 'purple';
export type MatchItemKey = 'time' | 'kills' | 'countdown' | 'daynight' | 'silenced' | 'teams' | 'hold';
export type StationDepartureReason = 'back_to_hud' | 'released';
export type TunnelStatus = 'off' | 'starting' | 'up' | 'error';
export type TunnelProviderValue = 'cloudflared' | 'manual';
/** 2026-09-16: the PRE-ARM CHECK's ACKED cell. `none` = no head pushed for this lobby; `waiting` = pushed,
 *  no answer yet (never a fault); `failed` = refused ack, offline or unbound phone, or no answer in time. */
export type SyncAckState = 'acked' | 'waiting' | 'failed' | 'none';
/** M7 (2026-10-10): every FIXED feed tag MC emits. The console tests a row's tag by exact value (Live.tsx), so this is the
 *  one list: API.md cites it, contract.gen.ts carries it, and `test_mc_feed_tags` fails on an emitted literal it lacks.
 *  A kill's medal tag is not fixed: the medal keys upper-cased and joined by " + " (`FIRST BLOOD + DOUBLE KILL`), or
 *  `STREAK ×N` (`scoring.py`). ALERT / WITHHELD / ROLE (A11.4, F118): a global-state alert reached everyone bound, reached
 *  nobody, or assigned a role; the `text` is the operator's third-person copy, rendered verbatim. OPERATOR (A47): the
 *  LIVE menu's RESYNC / RESPAWN / RELINK or a phone's answer. RECONCILED (A34), RESUMED (MC restarted into a match), NOTE
 *  (a match MC did not start). AFTER WHISTLE (F357): a kill that counts for nothing. TEAM CREDIT (A65): a kill credited to
 *  a team and no player. STATION (A67): an on-station range edit. */
export type FeedTagValue = 'TEAM KILL' | 'TEAM CREDIT' | 'AFTER WHISTLE' | 'SYNC POINT' | 'ALERT' | 'WITHHELD' | 'ROLE' | 'OPERATOR' | 'RECONCILED' | 'RESUMED' | 'NOTE' | 'STATION' | 'CONFIG' | 'END' | 'POWERUP' | 'RESCORED';
/** A47: the three operator actions MC may send to ONE bound player phone (`state.py operator_action`). */
export type OperatorCmd = 'resync' | 'respawn' | 'relink';

// ---- kind vocabularies ----
export const MC_KINDS = ['ack', 'alert', 'apply', 'assign', 'config', 'control', 'feedback', 'join', 'loadout_ack', 'pull_log', 'result', 'score', 'start', 'station_config', 'station_update', 'time_res', 'tutorial', 'welcome'] as const;
export type McKind = typeof MC_KINDS[number];
export const NODE_KINDS = ['ack_config', 'bind', 'event', 'event_batch', 'hello', 'loadout_browse', 'loadout_request', 'log_data', 'log_offer', 'ready', 'station_action', 'status', 'time_req'] as const;
export type NodeKind = typeof NODE_KINDS[number];
export const CONTROL_CMDS = ['abort_start', 'clock_resync', 'end', 'panic', 'recall', 'release_utility', 'relink', 'respawn', 'resync'] as const;
export type ControlCmd = typeof CONTROL_CMDS[number];
/** ⚠ This is a WHITELIST and an unlisted type is REJECTED at the socket, not ignored downstream --
 *  so a fact the phone learns to send reaches nothing until it is named here (the F40/F60 shape:
 *  both ends report healthy). `possession` is the objective-mode tally (mc/API.md, F70).
 *  A56 (S58): a player took a powerup station's item (never scored) */
export const PERSISTED_EVENT_TYPES = ['death', 'hit_taken', 'operator_result', 'pickup', 'possession', 'respawn', 'team_change'] as const;
export type PersistedEventType = typeof PERSISTED_EVENT_TYPES[number];
export const STATION_KINDS = ['respawn', 'powerup', 'extraction', 'bomb', 'control'] as const;
/** The command words a NODE must never write to its gun, whatever a bundle or a debug panel says:
 *  persistent state, pairing, DFU, the IR word-format switch, factory tests, and `$DPLAY`, which
 *  blocks the gun's main loop with the serial port unread (the likely screamer mechanism). One
 *  source, `protocol.DENIED_COMMANDS`; the phone reads this copy from the generated contract
 *  (docs/spec/transport-hardening.md §4). */
export const NODE_DENIED_COMMANDS = ['ASKSN', 'BOOM', 'BURN', 'CDFU', 'CLEARDEVICE', 'DDFU', 'DEV', 'DPLAY', 'DTYPE', 'DUTY', 'FACTORY', 'FTST', 'GPAIR', 'GPAIRX', 'HEADDFU', 'INQ', 'IRT', 'MUZ', 'PAIR', 'PIN', 'RESET', 'SETUP', 'SITE', 'SOL', 'TSTRNAME', 'VIBTOGGLE', 'ZOFF', 'ZOM', 'ZOMBIEKEYACTIVE', 'ZON', 'ZTOG'] as const;
export type NodeDeniedCommand = typeof NODE_DENIED_COMMANDS[number];
export const STATION_SOURCE_IDS = ['grenade', 'ir_station', 'phone'] as const;
export type StationSourceId = typeof STATION_SOURCE_IDS[number];

// ---- shapes (mcp/brx_mcp/mc/types.py TypedDicts) ----
export interface BleId {
  address?: string;
  uuid?: string;
  tail?: string;
}

export interface ArmoryRecord {
  gun_id: string;
  sticker: string;
  headset_pin: string;
  ble: BleId;
  gen: 'gen2_3' | 'gen1';
  fw: string | null;
  labeled: boolean;
  notes?: string;
}

export interface ScanRow {
  tail: string;
  name: string;
  basename: string;
  gun_id: string | null;
  rssi: number;
  identity: 'ok' | 'unconfirmed' | 'reverted' | 'unknown';
  t: number;
}

export interface WeaponSel {
  weapon_id: string;
}

/** Per-player accessibility + HP/armour handicap (modes §1.1). All keys are optional and
 *  independent -- `state.py _check_loadout` drops the whole `overrides` key when none survive
 *  validation. S50 (2026-09-17): `easy_reload` moved HERE from the perk slot, because it is
 *  accessibility (a player who cannot work the reload lever), not balance, so a left-handed player
 *  can take it with NO extra health, and a younger player can take it WITH one (Tony, 2026-09-17:
 *  "keep the two accessibility switches independent"). */
export interface LoadoutOverrides {
  /** 1..999 (`state.py _check_loadout`); 0 is a corpse, not a pool */
  max_hp?: number;
  /** 0..999 -- 0 is legal and means "one shot with a sniper" */
  max_armor?: number;
  /** ALT button = RELOAD ($BMAP,1,97); still can't ride with a second weapon or */
  easy_reload?: boolean;
}

/** weapons[] is canonical: [primary] or [primary, secondary]; `perk` is its OWN slot and rides
 *  beside a secondary weapon (AR + pistol + Quick Switch). The one exception: S50 (2026-09-17)
 *  moved it from a perk to `overrides.easy_reload` (a per-player accessibility switch, host-set
 *  only) -- it still takes the ALT button, so the server refuses it beside a second weapon; the
 *  host UI warns and drops the other one (A14, loadout.md §2/§2.1). */
export interface Loadout {
  /** [primary] or [primary, secondary]; index == gun slot; NEVER empty (A10) */
  weapons: WeaponSel[];
  /** A14: the perk slot — rides beside a secondary weapon (loadout.md §2) */
  perk?: string | null;
  overrides?: LoadoutOverrides;
}

export interface Team {
  team_id: string;
  name: string;
  color: string;
  tid: number;
}

export interface Player {
  player_id: string;
  /** 1..63 on the wire ($PSET token 1); 0 reserved */
  player_num: number;
  display: string;
  team_id: string | null;
  node_id: string | null;
  gun_id: string | null;
  loadout: Loadout;
  voice: string;
  ready: boolean;
  /** A15 (optional): {role: sound id} picks for the $PSET voice fields + the kill line -- WHICH death scream /
   *  pain line / respawn cry of the family the gun plays (voices.PSET_ROLES + "kill"). Absent = the family defaults. */
  voice_slots?: Record<string, string>;
}

/** F315: one `$HIR` word a weapon can put on the wire -- the IR protocol (`$WEAP` t3, the `$HIR` token 2
 *  the victim reads), the subtype (t4) and the magnitude (t5, t12 or t37). Every word of one `$WEAP` frame
 *  rides the frame's own t3/t4, the headset word included, so a weapon's entries share one cell. */
export interface HirCell {
  proto: number;
  subtype: number;
  mag: number;
}

/** S56: one weapon a roster player carries, so a victim's phone can name what hit it. */
export interface RosterWeapon {
  weapon_id: string;
  /** The `$HIR` token-5 magnitudes this weapon's words can carry (`$WEAP` t5, t12 when > 0, t37 when > 0),
   *  read from THIS player's compiled frame when MC holds one (a perk such as Armour Piercing changes them),
   *  else the catalogue's base values. Sorted, unique. */
  hir: number[];
  /** F315: the same words with the cell each one rides, from the same compiled frame (after any re-key:
   *  Armour Piercing, `--distinct-weapon-cells`), one entry per `hir` magnitude, sorted by it. The phone
   *  matches cell + magnitude first. Absent = an older MC; the phone then matches `hir` alone. */
  cells?: HirCell[];
}

export interface RosterEntry {
  player_id: string;
  player_num: number;
  display: string;
  team_id: string | null;
  /** S56: the player's loadout, slot order (primary first). Absent = an older MC; the phone then names no weapon. */
  weapons?: RosterWeapon[];
}

export interface Respawn {
  type: 'auto' | 'scanner' | 'none';
  delay_s: number;
  /** absent = TIMED_PROTECT_S_DEFAULT */
  protect_s?: TimedProtectS;
  /** absent = WEAPON_DELAY_MS_DEFAULT */
  weapon_delay_ms?: WeaponDelayMs;
  /** absent = STATION_PROTECT_S_DEFAULT */
  station_protect_s?: StationProtectS;
  /** F325: scanner respawn only (contracts §3, A13.1): "trigger" = at the station AND pull the trigger (the
   *  node's default when absent), "presence" = being at the station is enough. The node ignores it otherwise. */
  gate?: 'trigger' | 'presence';
}

/** The node's respawn frames (2026-09-19). Absent on an older bundle: the node keeps the legacy path
 *  (`spawn`/`revive`, protection ended by the first shot or SPAWN_PROTECT_MAX_MS). An app older than 0.4.3
 *  ignores this block and plays the legacy lists, so the legacy lists stay byte for byte as they were. */
export interface RespawnProfile {
  /** timed: t8 window after `$SPAWN`; 0 = the timed lists carry no `$TMP` */
  protect_ms: number;
  /** timed: when the node writes `trigger_live`, after the `$SPAWN` write */
  trigger_ms: number;
  /** station: t8 window; the trigger is live in the write itself */
  station_protect_ms: number;
  /** the T-0 spawn: $PLAYX,0 -> $SPAWN -> $TID -> $AMMO -> $BMAP,0,0 (no t8: everyone is live and hittable at go-live) */
  spawn: string[];
  /** a timed revive: $SPAWN -> [t8 -100] -> $TID -> $AMMO -> $BMAP,0,98 */
  revive: string[];
  /** a station revive: $SPAWN -> [t8 -100] -> $TID -> $AMMO -> $BMAP,0,0 -> [shield_on] */
  revive_station: string[];
  /** infection: the flip bursts, timed profile */
  team_flip?: Record<string, string[]>;
  /** `$BMAP,0,0,,,,,*` */
  trigger_live: string;
  /** a headset blink, distinct from the native hit flash; "" = no shield light */
  shield_on: string;
  /** the headset's in-play rest frame, written when station protection ends */
  shield_off: string;
}

export interface Scoring {
  frag_limit: number | null;
  win_by: WinBy;
  /** F415: KOTH only. The first team to hold the hill this long wins; else the most possession at the
   *  clock. Absent or None = no target (the pre-F415 rule). */
  hold_target_s?: number | null;
}

export interface Health {
  max_hp: number;
  max_armor: number;
  /** Tony 2026-09-19 (S45/§7.3): the `$PSET` t5 shield CEILING -- a host-facing field where there used
   *  to be none (`compile._GC_SHIELD_DEFAULT` armed a fixed 70 on every game, shields preset or not).
   *  0 = no shield at all. The Shields preset recharge (`app/src/engine.js shieldRegenOn`) turns on
   *  only when `max_armor == 0` AND this is `> 0` -- the same rule the node already keyed the S29
   *  mechanic on, now driven by a real number instead of a silent constant. */
  max_shield: number;
  /** Which named preset these three numbers ARE, or "custom" -- computed server-side
   *  (`compile.resolve_health_preset`) on every `PUT /api/config`, never hand-set by a client's own
   *  guess. A saved game from before this field existed (no `max_shield` at all) loads as "custom"
   *  (`state.py _merge_config`'s `health` branch), because its shield intent is unknown. */
  preset: HealthPreset;
}

/** S14: heal the killer on each kill (Fortnite/CoD "health on kill").
 *
 *  Both are **added** to the killer's own pool and clamped by the gun ($LIFE is additive-clamped),
 *  so they can never overfill. There is no `shield` term yet. The shield CAN be filled over BLE
 *  (`$LIFE,0,0,<n>,*`, F109, bench 2026-09-11), so one can be added if a mode wants it. Typed only:
 *  compile and the node do not act on `siphon` today (S14 open). */
export interface Siphon {
  hp: number;
  armor: number;
}

export interface SlotRule {
  choice: SlotChoice;
  /** primary/secondary: "weapon" | "sidearm" (A12); the perk rule is always ["perk"] (A14) */
  kinds: ItemKind[];
  exclude_tags: string[];
  exclude_ids: string[];
  only_ids: string[];
  fixed_id: string | null;
}

/** A14: `perk` is the third rule (kinds always ['perk']; choice may be 'off'). No legacy shape
 *  is supported (Tony 2026-09-04). */
export interface LoadoutPolicy {
  preset: LoadoutPreset;
  hud_select: boolean;
  primary: SlotRule;
  secondary: SlotRule;
  /** A14: perks are their own slot (choice may be "off") */
  perk: SlotRule;
}

/** allowed ids per slot, catalog order, computed server-side (loadout.md §3.2); `perks` is the
 *  perk slot's list (A14). */
export interface LoadoutPool {
  primary: string[];
  secondary_weapons: string[];
  /** A14: the perk slot's pool */
  perks: string[];
  reasons?: Record<string, PoolEmptyCode>;
}

/** The effect knobs the compiler acts on -- exactly `perks.EFFECT_KEYS`, which `PerkCatalog.__init__`
 *  refuses a perks.json row for exceeding. Every key is optional: a row carries only what it changes.
 *
 *  S50 (2026-09-17, docs/perk-design.md §2): `max_armor_add` is a FLAT armour grant/cost (body_armor
 *  +25, quick_switch -20) -- `compile._MAX_ARMOR_ADD` is the one table the compiled arithmetic reads,
 *  keyed by perk_id; this field is its wire-visible documentation, kept an integer because
 *  `app/src/hud/hud.js` / `webapp/mc/src/screens/Kit.tsx` render it literally. */
export interface PerkEffects {
  /** added to $PSET armour (or, base armour 0: $PSET shield) -- capped at 255, */
  max_armor_add?: number;
  /** floored at 0 (`compile.armed_armor`/`armed_shield`)
   *  scales the clip/reserve the head writes */
  ammo_mult?: number;
  /** D5 (2026-09-25, docs/perk-design.md §2): extended_mags' override for a */
  ammo_mult_pistol?: number;
  /** pistol primary (role `sidearm` or the `pistol` tag) -- read instead of
   *  `ammo_mult`, and rounded DOWN (`compile.py` `WeaponCatalog._ammo`)
   *  scales the weapon's reload time */
  reload_mult?: number;
  /** unused by any current row (S50: easy_reload moved to */
  alt_reload?: boolean;
  /** `loadout.overrides.easy_reload`) -- kept for a future ALT-button perk
   *  scales $WEAP tok15, the gun's swap delay (bench 2026-09-04) */
  switch_mult?: number;
  /** S50 (new, armor_piercing perk): primary's $SIR key -> the armour-piercing */
  armor_piercing?: boolean;
  /** cell, damage cut to `compile._AP_DAMAGE_MULT`. PRIMARY ONLY.
   *  F278 (2026-09-18): no row declares this yet -- filed and refused before it */
  crit_pct_add?: number;
}

export interface PerkView {
  perk_id: string;
  name: string;
  desc: string;
  tags: string[];
  mechanism: 'passive' | 'slot_frame';
  effects: PerkEffects;
  /** S50 (2026-09-19): player-facing GAIN lines, e.g. "+25 ARMOR" -- `perks.gain_cost_lines` */
  gain: string[];
  /** is the one place either UI reads this from (app/src/hud/hud.js, webapp/mc/src/screens/Kit.tsx)
   *  the same perk's COST lines, e.g. "RELOADS 1.3× SLOWER" -- empty when the perk carries none */
  cost: string[];
  verified: boolean;
  hidden: boolean;
  /** F551 (field 2026-10-17): the weapon ids this perk cannot ride with as the primary / the secondary -- the same rule
   *  the compile guards refuse a push on (`Compiler.perk_block_reason`). A kit picker hides the perk for those.
   *  Absent from an older MC: hide nothing. */
  blocked_primary?: string[];
  blocked_secondary?: string[];
}

/** S50 build 4: a wire number before and after a perk touched it. Integers, always both present
 *  together (never just one). */
export interface ValuePair {
  base: number;
  resolved: number;
}

/** S50 build 4 (`docs/spec/loadout.md` §1.2/§2): the RESOLVED, per-player perk effect, exactly as
 *  it was compiled into this bundle -- not the catalogue's `PerkEffects` (which is unresolved and
 *  pool-independent). A field is present only when the perk actually changed it; `perk_id` is present
 *  whenever the player carries a perk, even one with no other field here, so a phone/console can show
 *  an icon. Lives on `FrameBundle.perk_effects` (the persisted per-player config, survives an app
 *  restart) and, per player, on `State`'s roster/player view for Mission Control's console. */
export interface PerkEffectsResolved {
  perk_id?: string;
  mag?: ValuePair;
  reserve?: ValuePair;
  reload_ms?: ValuePair;
  swap_ms?: ValuePair;
  max_hp?: ValuePair;
  max_armor?: ValuePair;
  max_shield?: ValuePair;
}

/** A56 (S58, docs/spec/powerups.md): what a `powerup` station grants, and when it spawns on the match clock.
 *  A weapon item grants `charges` rounds of `weapon_id` (armed at start in a spare slot, `GameConfig.powerups`);
 *  an overshield grants `amount` shield on top, hit first, no regen, gone at death. `spawn_every_s`/`first_at_s`
 *  are a positive integer (ARMORY's own per-station override caps `spawn_every_s` 30-240, `powerups.py`
 *  `SPAWN_EVERY_MIN`/`MAX`; the schedule mechanism itself tolerates any positive value); a spawn further off
 *  than the advert's value byte (255 s) just clamps the claim-proximity advert's remaining-seconds
 *  DISPLAY, it does not touch the real schedule (`station_update.next_spawn_in_ms` carries the true value).
 *  `name` is at most 12 characters; `color` is `#rrggbb`. */
export interface StationItem {
  kind: StationItemKind;
  weapon_id?: string;
  charges?: number;
  amount?: number;
  spawn_every_s: number;
  first_at_s: number;
  name: string;
  color: string;
}

/** A56: one item the host can pick for a powerup station (`GET /api/powerups`), MC's defaults expanded.
 *  `preset` is what `PUT` sends back as `item_preset`. */
export interface PowerupPreset {
  preset: string;
  item: StationItem;
}

/** A56: `GET /api/powerups`. `enabled` is MC's powerups flag (off until the bench passes); the console hides
 *  the item picker when it is false. */
export interface PowerupsView {
  enabled: boolean;
  presets: PowerupPreset[];
}

/** A56: a pickup weapon MC armed at start (empty, out of the ALT cycle) and the gun slot it went into (2 or 3). */
export interface PowerupSlot {
  weapon_id: string;
  slot: number;
}

/** One armed utility item on `GameConfig.stations` -- exactly what `state.py _station_ids()` builds
 *  (`{"id": a["id"], "kind": a["kind"]}`), sorted by id. `item` (A56) rides along for a powerup station, so a
 *  player's phone knows the item and its spawn schedule without MC. */
export interface StationRef {
  id: number;
  kind: StationKind;
  item?: StationItem;
}

export interface Stun {
  /** F15/A20: seconds a hit EMP keeps the gun disarmed (default 10, 1..60) */
  duration_s?: number;
}

/** S16: one damage-over-time weapon's tick numbers, as the VICTIM's node needs them. The victim knows only
 *  its own loadout, so MC ships a game-wide table in `FrameBundle.dot`, keyed by the IR protocol the shooter's
 *  `$WEAP` t3 carries (the `$HIR` token 2 the victim reads). Built by `Compiler.dot_table()` from every weapon in
 *  the game whose `weapons.json` row declares `dot`. `spec/node.md` §3.17 holds the rules the node runs. */
export interface DotSpec {
  weapon_id: string;
  /** damage one tick takes from the outermost non-empty pool */
  per_tick: number;
  /** the interval between ticks */
  tick_ms: number;
  /** how long one hit keeps the stack alive; a second hit REFRESHES it, never stacks */
  duration_ms: number;
}

/** S42 (2026-09-17): a weapon's TARGET accuracy profile -- `weapons.json` `recoil`, declared-only
 *  on the wire (compile.py `resolve()` never writes t21/t22 from it). `app/src/engine.js` is the sole
 *  reader. **F259 (2026-09-18): a STATE MACHINE, not a per-shot walk** -- `_recoilProfile` derives
 *  `crisp`/`degraded`/`heavy` states from this shape (`ceiling`/`floor` become `crisp`/`degraded`):
 *  CRISP until the burst reaches `after_shots` rounds (DEGRADED), HEAVY after `after_heavy`, and back
 *  to CRISP in one step once the trigger is quiet for `settle_ms`.
 *
 *  **S54/F268/F280 (2026-09-23): `after_shots`/`after_heavy` derive from ROUNDS PER TRIGGER PULL scaled
 *  by calibre, not from the ladder's depth.** A weapon dealing the engine's reference damage (8, the
 *  Assault Rifle/SMG/Energy Rifle) fires 5 clean rounds and degrades on the 6th, then 3 more clean
 *  rounds and goes heavy on the 9th; a different `dmg` scales both counts by `8 / dmg`, so a bigger
 *  round kicks in sooner. The four legacy fields (`ceiling`, `floor`, `per_shot`, `recover_ms`) remain
 *  accepted as derivation inputs for `crisp`/`heavy`/`settle_ms`; `per_shot` no longer sizes anything.
 *  The six explicit fields are optional per-weapon overrides that win outright over the derivation
 *  (S54). `app/src/engine.js` also resets a still-CRISP burst on the gun's own trigger-release edge
 *  (`$BUT,0,0`), at no cost in writes; a DEGRADED or HEAVY weapon still recovers only on `settle_ms`
 *  quiet, in one write (bench-provisional). */
export interface Recoil {
  ceiling: number;
  floor: number;
  per_shot: number;
  recover_ms: number;
  crisp?: number;
  degraded?: number;
  heavy?: number;
  after_shots?: number;
  after_heavy?: number;
  settle_ms?: number;
}

/** F559: a game's hill tuning, sent to every control station it arms. A key that is absent keeps the station's own
 *  value (its +/- buttons); a key MC sends wins on that arming (no edit ages: a hill keeps no edit record). */
export interface HillSettings {
  /** HILL_CAPTURE_S_MIN..MAX seconds */
  capture_s?: number;
  /** HILL_NET_CAP_MIN..MAX */
  net_cap?: number;
}

export interface GameConfigBase {
  config_id: string;
  mode: string;
  environment: 'indoor' | 'outdoor';
  night: boolean;
  /** required (>0) on the phone path; None only for full-coverage venues */
  time_limit_s: number | null;
  respawn: Respawn;
  scoring: Scoring;
  health: Health;
  teams: Team[];
  led?: Record<string, unknown>;
  /** A6.5 */
  player_num_base?: number;
  /** S14: heal-on-kill; absent or {0,0} = off */
  siphon?: Siphon;
  /** A13.1 (F104): the utility items MC armed for THIS game, when at least one is assigned. */
  stations?: StationRef[];
  /** A56 (S58): pickup weapons armed at start in spare slots; absent = none (or the flag is off)
   *  Set by `Session._wire_config()` from the ITEMS assignments, never by the
   *  operator; a player phone honours only these ids (`engine.js _stationAllowed`) --
   *  and when the list is ABSENT (nothing assigned) it honours ANY station (the hand-armed fallback). */
  powerups?: PowerupSlot[];
  /** F-hotfix (contracts A-row): the advert `game` byte (1..255) MC arms its stations with
   *  (`station_config.game`) for THIS match. Set by `Session._wire_config()`; a player phone
   *  scopes presence and its own advert by it. Absent (an older MC) = 0, any game. */
  game_byte?: number;
  /** Derived scanner fallback: teams without a station use timed AUTO respawn. */
  respawn_auto_teams?: number[];
  /** F70: what is emitting this game's objective -- `STATION_SOURCES` above
   *  ("grenade" = a BRX Smart Grenade in hill mode, "ir_station" = a
   *  $CAPTURE-speaking station). Present only for the modes that need one
   *  (domination/koth/ctf/cs/bomb); `validate()` refuses those without it. */
  station_source?: string;
  /** A11 (mc/presentation.py): sounds + lights per event, preset or custom */
  presentation?: Record<string, unknown>;
  /** A17: per-WEAPON $SIR sounds. DEFAULT OFF -- bench F38: a non-empty
   *  $SIR sound REPLACES the $PSET pool sound rather than layering, so
   *  turning this on SILENCES the ear-confirmed material layer (armour
   *  metal / shield fizz / silent health) on every standard hit. */
  hit_audio_class?: boolean;
  /** A17: give each weapon FAMILY its own $SIR cell so hits sound different
   *  per weapon. DEFAULT OFF -- an unmatched cell is silently ignored (the
   *  F11 shape), so it stays off until FOLLOWUPS F38/F39 clear it at the bench. */
  hit_audio_rekey?: boolean;
  /** F15/A20: the host-driven STUN (EMP). Present = the `<8,0>` $SIR cell
   *  ships as fn 23 (status, no damage; F253) and a proto-8 $HIR disarms the
   *  victim's node for `duration_s` (default 10, 1..60). Absent = the stock
   *  charge-rifle damage row, byte-for-byte. Source: a $WEAP t3=8 slot
   *  (the charge rifle) or a proto-8 station. */
  stun?: Stun;
  /** A31/A4.8: the VENUE's radio coverage -- "full" = every phone is on
   *  the LAN for the whole match (the only case where `time_limit_s` may
   *  be null and where an MC-decided end needs no "verify at MC" warning).
   *  Absent/anything else = partial. `compile.full_coverage()` is the one
   *  reader; `opts.coverage` (the CLI/sim path) still wins. */
  coverage?: 'full' | 'partial';
  /** A18 (E1): the MODE's own rules -- what its engine declares in `PARAMS`
   *  (`modes/params.py`; schema per mode from `GET /api/modes`). Present, and
   *  COMPLETE (defaults filled), for every mode whose engine declares any;
   *  absent for one that declares none (tdm/ffa/infection), so those configs
   *  are byte-identical to before the field existed. Unknown keys and
   *  out-of-range values are refused at PUT and again by `validate()`.
   *  Rides the wire as-is: a node reads its rules from here, never from a
   *  schema of its own. */
  mode_params?: Record<string, number | boolean | string>;
  /** A19 (S10): who the VIP is. Must name a rostered player (`validate()`);
   *  MC pushes them the `vip` headset role (`alert.role`) once the match is
   *  live and again after each of their respawns. Never stored in a saved
   *  game (a preset names no person). */
  vip_player_id?: string | null;
  /** S42: node-driven recoil (the accuracy ceiling/floor is OURS, not the
   *  gun's native walk -- F230). DEFAULT ON: absent or `true` = on, only an
   *  explicit `false` turns it off. No FrameBundle change needed -- `config`
   *  already rides every push wholesale, and `app/src/engine.js` reads
   *  `config.recoil !== false`. Seam for stance/flinch (also S42, not built
   *  here): a future switch for either can sit right beside this one. */
  recoil?: boolean;
  /** K8: the host's match-head $VOL, an integer 60..100
   *  (`compile.GAME_VOLUME_MIN/MAX`). Absent or null = the venue volume
   *  (`compile.play_volume`: 80 indoors, 90 outdoors); a null PUT removes
   *  the key. `--bench-volume` overrides this value and try-outs; without
   *  it, a try-out plays at VOL_TRYOUT (69), never this value. */
  volume?: number | null;
  /** F559: capture time and net cap for every control station. A set key
   *  wins on every arming; absent = the station keeps its own. A PUT of
   *  null clears it; a mode change carries it, like `volume`. */
  hill?: HillSettings | null;
}

/** A complete config type whose policy may be omitted for server defaulting. */
export interface GameConfig {
  config_id: string;
  mode: string;
  environment: 'indoor' | 'outdoor';
  night: boolean;
  time_limit_s: number | null;
  respawn: Respawn;
  scoring: Scoring;
  health: Health;
  teams: Team[];
  led?: Record<string, unknown>;
  player_num_base?: number;
  siphon?: Siphon;
  stations?: StationRef[];
  powerups?: PowerupSlot[];
  game_byte?: number;
  respawn_auto_teams?: number[];
  station_source?: string;
  presentation?: Record<string, unknown>;
  hit_audio_class?: boolean;
  hit_audio_rekey?: boolean;
  stun?: Stun;
  coverage?: 'full' | 'partial';
  mode_params?: Record<string, number | boolean | string>;
  vip_player_id?: string | null;
  recoil?: boolean;
  volume?: number | null;
  hill?: HillSettings | null;
  loadout_policy?: LoadoutPolicy;
}

/** A config MC serves in State or from a successful config/preset response.
 *
 *  PUT bodies use ``GameConfig`` with optional fields, since callers may update only selected keys.
 *  Served configs have gone through the server's policy fill and always include ``loadout_policy``. */
export interface ConfigView {
  config_id: string;
  mode: string;
  environment: 'indoor' | 'outdoor';
  night: boolean;
  time_limit_s: number | null;
  respawn: Respawn;
  scoring: Scoring;
  health: Health;
  teams: Team[];
  led?: Record<string, unknown>;
  player_num_base?: number;
  siphon?: Siphon;
  stations?: StationRef[];
  powerups?: PowerupSlot[];
  game_byte?: number;
  respawn_auto_teams?: number[];
  station_source?: string;
  presentation?: Record<string, unknown>;
  hit_audio_class?: boolean;
  hit_audio_rekey?: boolean;
  stun?: Stun;
  coverage?: 'full' | 'partial';
  mode_params?: Record<string, number | boolean | string>;
  vip_player_id?: string | null;
  recoil?: boolean;
  volume?: number | null;
  hill?: HillSettings | null;
  loadout_policy: LoadoutPolicy;
}

export interface FrameBundle {
  config_id: string;
  player_id: string;
  /** config head, NO $SPAWN, no countdown sound; ends with $TID */
  head: string[];
  /** $PLAYX,0 -> $SPAWN,, -> $TMP t8=-100 -> $TID -> $AMMO... -> $BMAP,0,0 (F121 rebuild: no $SIR row; the table survives $SPAWN) */
  spawn: string[];
  /** $SPAWN,, -> $TMP t8=-100 -> $TID -> $AMMO... -> $BMAP,0,0 */
  revive: string[];
  /** 2026-09-19: timed vs station respawn frames; an app >= 0.4.3 plays these */
  respawn_profile?: RespawnProfile;
  /** F121 rebuild: `$TMP` t8=0, written on the first shot or the cap; absent = an older bundle */
  spawn_protect_off?: string;
  end: string[];
  panic: string[];
  team_flip?: Record<string, string[]>;
  /** F86: per-tid [blank, rest] the node takes the gun with after a flip */
  team_flip_take?: Record<string, string[]>;
  /** A6.3: key -> PRE-COMPOSED frame the node writes verbatim. countdown, kill,
   *  game_over?, victory?, tick?, klaxon?, multi?, medal?, runway_*?, and the once-per-life
   *  low-health pair hurt?/hurt_led? (hurt_led is an $HLED, not a $PLAY — see compile.cues)
   *  A11: plus one key per presentation EVENT that carries a sound (hit_taken … vip_down); "" = deliberately mute.
   *  A15.2: `spawn` = the character's spawn line, written by the node IMMEDIATELY after the spawn / revive frames
   *  (the head's $PSET ships an empty battleRespawnCry, so the firmware itself says nothing on $SPAWN).
   *  A15.3: `pain_short` / `pain_long` / `pain_melee` = the pain the node plays on a $HIR (the $PSET pain fields ship
   *  empty): a melee word -> pain_melee; damage >= voice.pain_long_min -> pain_long; else pain_short. At most one per
   *  600 ms, none on the lethal hit (the firmware's death scream covers it). */
  cues: Record<string, string>;
  /** A11: event -> [[frame, hold_s], ...] -- the tuned $GLED burst (+ optional $HLED) */
  leds?: Record<string, unknown[]>;
  /** A11: presentation.summary() -- preset + switches, for the UI/HUD */
  presentation?: PresentationSummary;
  /** A11.7: {in_play team|dark|health, blank, rest, bands?[[frac,f]]} -- absent for native */
  gun?: Record<string, unknown>;
  /** A11.6: {in_play, rest, blank, pregame[], start[[f,s]], hit[[f,s]], death[[f,s]], respawn[[f,s]], carrier{tid:[[f,s]]}} */
  headset?: Record<string, unknown>;
  /** 2026-09-04: the weapon-swap delay the gun enforces (max tok15 of slots 0/1, after perks) */
  swap_ms?: number;
  /** A15.1: event -> frames; the node picks ONE at random per event; `cues[ev]` is the deterministic first */
  cue_pools?: Record<string, string[]>;
  /** A15: {id, family, pset{role: id}, kill, rolled{role: id} (A15.1: this push's draws), pools{role: [ids]},
   *  spawn: [ids] (A15.2: the spawn pool; `pset.respawn_cry` is "" unless picked),
   *  pset_pool: [death-scream ids, one per `pset_pool` frame], pain_long_min: int} (A15.3) */
  voice?: Record<string, unknown>;
  /** A15.3: the node writes ONE of these at random immediately before every `$SPAWN` (spawn and revive),
   *  so the firmware's death scream changes per life. One full $PSET per death-scream take; only the
   *  deathScream token differs. A pinned `death_scream` (or a one-take family) = one frame = head[4].
   *  A17: each take ALSO carries its own hitHp/hitArrmor/hitShield/hitCrit draw (hitaudio.MATERIAL_POOLS). */
  pset_pool?: string[];
  /** A17/A44: one full live `$SIR` table per take, the ONLY live carrier -- the node writes one in front of `spawn_protect_off` when the gun's table is not live or class sounds are on, and again after a
   *  lull, so the same weapon does not land the same clip all match. Re-sending `$SIR` rows is the F11 repair
   *  path, so the write is safe by construction; the rows are identical apart from their sound tokens. */
  sir_pool?: string[][];
  /** A17: {rekey: bool, cells{weapon_id: "p,s"}, classes{"p,s": family}, shared[families sharing a cell],
   *  material[roles]} -- what the UI/console shows for "what does a hit sound like", and what a bench probe reads. */
  hit_audio?: Record<string, unknown>;
  /** physical gun/headset word pairs for node-side accuracy grouping */
  dual_emitters?: Record<string, unknown>[];
  /** S16: IR protocol (a string key: JSON has no integer keys) -> tick numbers,
   *  for every damage-over-time weapon in THIS GAME. Absent = no such weapon. */
  dot?: Record<string, DotSpec>;
  /** S50 build 4: this player's compiled perk effect,
   *  absent when they carry no perk. Persisted here (not a
   *  one-shot message) so it survives an app restart. */
  perk_effects?: PerkEffectsResolved;
  /** S57 (docs/ir-callouts.md): the smallest team id in 0..3 that
   *  no player in this match holds, or None when all four are in use.
   *  Every player's dead-man IR callout word (protocol 15) carries this
   *  team, so a receiving phone hears it without it landing on a real
   *  team's own id. The same value in every player's bundle for one match. */
  callout_team?: number | null;
}

export interface Weapon {
  weapon_id: string;
  name: string;
  cls: string;
  /** ballistic|energy|melee (weapons.json `class`, A10, 2026-09-17): ballistic reloads, energy overheats/charges; not the same as `cls` above (raw protocol class byte) */
  weapon_class: string;
  /** house-written armory blurb (weapons.json `desc`); "" if a row lacks one */
  desc?: string;
  stats: Record<string, unknown>;
  weap_frame: string;
  icon?: string;
  verified?: boolean;
  /** A10 policy vocabulary (loadout.md §1.1) */
  tags?: string[];
  role?: string;
  /** F411 (2026-09-26): the loadout-preset vocabulary BUILD's type toggles union over (games-presets.md) -- rifle|close|long|sidearm|support, several per row allowed, [] on a pickup-only heavy */
  types?: string[];
  /** A10: human copy for a known LIVE problem (weapons.json `caution`) */
  caution?: string;
  /** 2026-09-17: catalogue-visible but never in a player loadout pool (policy.py) */
  pickup_only?: boolean;
  /** S42: the declared target accuracy profile (weapons.json `recoil`) */
  recoil?: Recoil;
  /** A48: rounds of the cell one FULL charge spends. `WeaponCatalog.rounds_per_charge()` resolves weapons.json's absent-means-1 row to a concrete integer, so a real compiled Weapon always carries this; NotRequired only for a hand-built fixture that skips it */
  rounds_per_charge?: number;
  /** 2026-09-18, weapon-design.md §7.4: False = cannot kill; absent means true */
  lethal?: boolean;
  /** F62 (2026-09-18): $WEAP t6 primaryCritChance, 0-100; absent = never crits */
  crit_pct?: number;
  /** victim-side runtime floor, declared beside the mechanic that needs it */
  min_app?: string;
  /** one trigger emits separate gun and headset words */
  dual_emitter?: boolean;
  /** weapons.json: chain = shell by shell, bolt = a lever pull per shot */
  reload_type?: 'chain' | 'bolt';
}

export interface WeaponBars {
  power: number | null;
  rof: number | null;
  ammo: number | null;
  ttk: number | null;
}

/** Host-health-ranked arsenal row built by views.weapon_view(s). */
export interface WeaponView {
  weapon_id: string;
  name: string;
  cls: string;
  /** ballistic|energy|melee (weapons.json `class`, A10, 2026-09-17): ballistic reloads, energy overheats/charges; not the same as `cls` above (raw protocol class byte) */
  weapon_class: string;
  desc: string;
  clip: number;
  mags: number;
  reserve: number | null;
  reload_s: number | null;
  reload_ms: number | null;
  dmg: number | null;
  rpm: number | null;
  rng: number | null;
  dmg_per_hit: number | null;
  /** one trigger can emit separate gun and headset words */
  dual_emitter?: boolean;
  /** policy.chain_reload: a HELD per-shell reload (the Shotgun) conflicts with Easy Reload. The producer always fills it
   *  (mc.md #4, 2026-10-10), so the console asks this row instead of a hand list of chain weapons.
   *  bolt: one round, a lever pull per shot (2026-10-17) */
  reload_type?: 'chain' | 'magazine' | 'bolt';
  /** older MC rows predate host-pool ranking; the current producer always fills it */
  pool?: number;
  verified: boolean;
  tags: string[];
  role: string;
  /** F411 (2026-09-26): rifle|close|long|sidearm|support, several allowed, [] on a pickup-only heavy -- NotRequired so a console reading an older server (games-presets.md's own stale-server rule) degrades to no type toggles rather than crashing on `undefined.includes` */
  types?: string[];
  htk: number | null;
  /** older MC rows can omit this derived figure */
  ttk_ms?: number | null;
  caution?: string;
  ammo_total?: number;
  bars?: WeaponBars;
  /** 2026-09-17: catalogue-visible but never in a player loadout pool (policy.py) */
  pickup_only?: boolean;
  /** 2026-09-18 (weapon-design.md §7.4): FALSE on a weapon that deliberately */
  lethal?: boolean;
  /** cannot kill (the fn-20 Breacher, the fn-23 Haze). It may never be a PRIMARY:
   *  the server refuses one in slot 0 and both UIs mirror that, so the field has
   *  to travel with the row or a console offers a pick that is refused at arming.
   *  S42: the declared target accuracy profile -- the node's `weaponRow(id).recoil` */
  recoil?: Recoil;
  /** A48: rounds of the cell one FULL charge spends -- the HUD's NOT ENOUGH ENERGY line reads this, never a hard-coded cost. `views.weapon_view()` resolves the catalogue's absent-means-1 row, so a real WeaponView always carries this; NotRequired only for a hand-built fixture that skips it */
  rounds_per_charge?: number;
  /** F62 (2026-09-18): $WEAP t6 primaryCritChance, 0-100; absent = never crits */
  crit_pct?: number;
  /** S56: the base `$HIR` t5 magnitudes this weapon can emit (t5, t12, t37 when > 0), sorted, unique -- the phone's pickup fallback when a hit matches no roster weapon */
  hir?: number[];
  /** F315: the same magnitudes with the catalogue frame's own cell (t3/t4), one entry per `hir` value -- a match's `--distinct-weapon-cells` move is in the roster's `cells`, never here */
  cells?: HirCell[];
}

export interface ModePiece {
  /** a `GET /api/modes` mode; the rest of the mode's defaults come from there */
  mode: string;
}

export interface LifePiece {
  max_hp: number;
  max_armor: number;
  max_shield: number;
}

export interface MiscLoadoutsPiece {
  /** True = PLAYERS pick on the phone, False = the HOST picks */
  hud_select: boolean;
  /** False = exclude_tags ["heavy"] on primary + secondary (a slot piece's own tags win) */
  heavies: boolean;
}

export interface GameplayPiece {
  /** MVP: {} = OPEN BRX STANDARD (each mode's own defaults) */
  mode_params: Record<string, unknown>;
}

/** One named preset for one PLAY picker. `value` is the kind's shape: mode -> ModePiece, life -> LifePiece,
 *  spawn -> Respawn, primary/secondary/perks -> SlotRule, misc_loadouts -> MiscLoadoutsPiece,
 *  gameplay -> GameplayPiece. Builtins carry ids `builtin:<kind>:<slug>` and cannot be edited or deleted. */
export interface GamePiece {
  piece_id: string;
  kind: PieceKind;
  /** <= 24 chars, unique per kind (case-insensitive) */
  name: string;
  /** one line, <= 80 chars; "" = none */
  note: string;
  builtin: boolean;
  /** True: shown greyed in BUILD, never offered on PLAY */
  post_mvp: boolean;
  created_t: number;
  updated_t: number;
  value: Record<string, unknown>;
  /** F411 review round 3, HIGH 1: absent normally. Present (the plain ALL-CAPS reason, e.g. "NAMES
   *  FORCE RIFLE, WHICH IS NO LONGER OFFERED: PICK A DIFFERENT WEAPON OR PERK") when a rule change
   *  elsewhere (a weapon hidden or turned pickup-only, a tightened check) makes `value` one the server
   *  would now refuse. The piece is KEPT, never silently dropped: BUILD shows it read-only with this
   *  reason, it is never pickable (PLAY/LOAD treat its id like a vanished one -- named = 400, inherited
   *  = falls back), and it survives every future save untouched until a PUT supplies a value the
   *  current rules accept, which clears this field. */
  invalid?: string;
}

/** Per-game values on the PLAY strip. Never saved into a piece; kept by PLAY AGAIN. */
export interface MatchSettings {
  time_limit_s: number | null;
  frag_limit: number | null;
  night: boolean;
  silenced: boolean;
  /** F413: the team colours in play, in order (2 to 4, unique; KOTH exactly 2 and never yellow). Absent
   *  for a mode without teams (FFA). The count is the list's length. */
  teams?: TeamColour[];
  /** F415: KOTH's hold target (see Scoring.hold_target_s) */
  hold_target_s?: number | null;
}

/** F411 LAST MATCH: the strip values of the last match STARTed, kept across an MC restart. */
export interface LastMatch {
  time_limit_s: number | null;
  frag_limit: number | null;
  night: boolean;
  silenced: boolean;
  teams?: TeamColour[];
  hold_target_s?: number | null;
  countdown_s: number;
}

/** What PLAY has picked: one piece id per kind, plus the strip. The config is composed from it. */
export interface GamePick {
  /** PieceKind -> piece_id, every kind present */
  pieces: Record<string, string>;
  match: MatchSettings;
}

/** F411 §6: a named bundle of the whole PLAY pick (games-presets.md §6) — "like a named LAST
 *  MATCH" (Tony). Stores piece REFERENCES, not copies: a favourite tracks its pieces' current
 *  values, and a piece deleted after being favourited falls back to that kind's first builtin at
 *  LOAD time (`POST /api/favourites/{id}/load`'s `fallbacks`), never a 404 for the favourite itself. */
export interface Favourite {
  favourite_id: string;
  /** <= 24 chars, unique (case-insensitive) */
  name: string;
  created_t: number;
  updated_t: number;
  pick: GamePick;
  /** the arm runway this favourite loads (games-presets.md §2 COUNTDOWN) */
  countdown_s: number;
}

export interface Preflight {
  ssid_ok?: boolean;
  mc_reachable?: boolean;
  auto_join_ok?: boolean;
  cellular_off?: boolean;
  dnd_on?: boolean;
  phone_batt?: number;
  screen_on?: boolean;
  foreground?: boolean;
  gun_linked?: boolean;
  headset_ok?: boolean;
  /** Bench 2026-09-17: true while the gun keeps dropping the link seconds after each connect (2+ quick
   *  drops in a row, BrxLink.flapping), which is what a headset that is off looks like. Optional. */
  gun_flapping?: boolean;
}

/** One player or utility node in `State.snapshot()`.
 *
 *  `last_seen_ms` is an age in this public view. The session keeps the corresponding node record's
 *  receive timestamp internally and projects it at snapshot time, so the UI never receives the
 *  host's wall clock. The optional fields are forwarded only after the node has reported them. */
export interface NodeView {
  node_id: string;
  node_type: string;
  arm_state: ArmState;
  last_seen_ms: number;
  synced: boolean;
  /** 2026-09-19 (two field bugs, a station and a rejoined phone kept "online"): the net layer's own
   *  freshness flag (STALE_AFTER_MS = 8 s of silence,
   *  `net.py`'s `_stale_loop`/`on_stale`/`on_return`), projected here so a client reads MC's judgement
   *  instead of re-deriving one from `last_seen_ms` with its own, disagreeing threshold. A stale node's
   *  `gun_linked`/`preflight`/`arm_state` are last-known facts, not current ones — the console must show
   *  OFFLINE and treat them as unknown, never green/connected. */
  stale: boolean;
  gun_name?: string;
  gun_tail?: string;
  player_id?: string;
  preflight?: Preflight;
  battery?: number | null;
  fw?: string | null;
  hp?: number | null;
  armor?: number | null;
  ammo?: number | null;
  alive?: boolean | null;
  pending?: number | null;
  /** O6: facts the phone's outbox dropped from the match in play now (the phone's own per-match count,
   *  `status.outbox_lost.n`, shown only while its `match_id` is the current / resumed / adopted match).
   *  Absent = nothing lost from this match, or an older node. */
  outbox_lost?: number;
  /** O10: CLAIM reports a Stick's queue evicted when full since it was armed for THIS game (`status.actions_dropped`,
   *  shown only while `status.actions_dropped_game` is the current game byte). MC never heard who took the item, so the
   *  station's attention line says where to look (the recap's PICKUPS). A Stick has no node card, so the console draws
   *  it on the station card. Absent = none. */
  claims_dropped?: number;
  app_ver?: string | null;
  platform?: string | null;
  /** F564: the phone's make and model (`Device.getInfo()`), e.g. "Google Pixel 4" */
  device?: string | null;
  log?: LogView | null;
  /** F309: the phone's own last `status.transport` claim; absent = never reported (older app). */
  transport?: 'wifi' | 'cellular' | 'none' | 'unknown';
  reach?: 'lan' | 'backhaul';
  last_reach?: 'lan' | 'backhaul';
  /** F208: the node's last `status.pool_stale` / `pool_stale_ms`. Absent = not stale, or an older app. */
  pool_stale?: 'silent' | 'no_fire' | 'write_lost' | 'pool_wrong';
  pool_stale_ms?: number;
  /** F264: what the node ITSELF did about a `pool_stale` claim, so the board reads more than "stale".
   *  `asking` = a $QUERY/$LIFE probe is out; `dead` = the gun answered health 0 and the death is booked;
   *  `alive` = it answered above 0 and the node re-asserted the arming, never a revive; `no_answer` =
   *  nothing came back and the node deliberately did NOTHING. `no_answer` is the one that needs a human. */
  cure?: 'asking' | 'dead' | 'alive' | 'no_answer';
  /** F272: the node positively proved that the linked gun stopped answering. Optional and true-only:
   *  absence is an older/healthy node, never evidence of a lock-up. */
  gun_locked?: boolean;
}

/** O6: `status.outbox_lost`: how many of match `match_id`'s facts the phone's outbox dropped. */
export interface OutboxLostReport {
  match_id: string;
  n: number;
}

export interface Event {
  type?: 'hit_taken' | 'death' | 'respawn' | 'team_change' | 'status' | 'possession' | 'operator_result' | 'pickup';
  t?: number;
  match_id?: string | null;
  node_id?: string;
  player_id?: string | null;
  /** hit_taken / death */
  shooter_num?: number;
  shooter_team?: number;
  dmg?: number;
  ir_proto?: number;
  ir_subtype?: number;
  shot_group?: number | string;
  /** $HIR tok1 — WHICH sensor caught the shot. 0-3 are ALL HEADSET sensors (the headset carries
   *  FOUR, operator-confirmed 2026-09-01; only 0 = front and 1 = back are bench-mapped), 4 = gun
   *  body. Forwarded 2026-09-01: it was parsed on the phone and dropped, so a
   *  "the headset domes never register" report could only be checked against a frame ring. */
  sensor?: number;
  desync?: boolean;
  /** S16: the death came from the node's own poison tick (a `$LIFE` write), not from a hit. `shooter_num` and
   *  `shooter_team` then name the player who last applied the poison, which is who gets the kill. */
  dot?: boolean;
  /** Tony 2026-09-24 (death): the killing $HIR was the melee proto (13) -- the melee medal. Absent on an older phone. */
  melee?: boolean;
  /** A65 (F354, death): the victim's phone lost the damaging hit and only a non-damaging word (smoke, EMP) was fresh,
   *  so it credits that word's TEAM (`shooter_team`) and no player (`shooter_num` 0). The team score counts the kill;
   *  no player gets the K, a medal, a chain, first blood or an assist. Absent on an older phone. */
  credit?: 'team';
  /** S56 (hit_taken): the weapon the victim's phone resolved from the shooter's roster loadout; absent = unresolved or ambiguous. */
  weapon_id?: string;
  /** respawn */
  resync?: boolean;
  /** A47: the operator's FORCE RESPAWN, not a respawn after a death (scoring keeps the streak) */
  operator?: boolean;
  /** F289 (respawn and an infection team_change): the ms of spawn protection the phone must end itself; absent =
   *  none owed. Sent at once with the respawn, so MC knows of the window even when the phone dies inside it and no status follows. */
  protect_ms?: number;
  /** operator_result (A47): what the phone DID with an operator action MC sent (`control{resync|respawn|relink}`).
   *  Persisted like every fact, and read for the operator's feed and menu only: it never reaches the scorer. */
  cmd?: OperatorCmd;
  ok?: boolean;
  /** present on a refusal: the phone's own reason ("stunned", "not live", ...) */
  why?: string;
  /** pickup (A56, S58): the player took a powerup station's item. Presentation and station state only; never scored. */
  station_id?: number;
  item_kind?: StationItemKind;
  /** F473: the station's advertised seconds to its NEXT spawn when the phone was granted; names the spawn the fact is about (absent from an older phone) */
  next_spawn_in_s?: number;
  /** team_change */
  tid?: number;
  /** possession (F70, objective modes) — a CUMULATIVE tally for ONE control point, resent as it grows.
   *  `hold_ms` maps a TEAM TID (as a string key on the wire: JSON has no integer keys) to the ms this
   *  node observed that team OWNING the point; tid 2 on a hill is NEUTRAL, not a team. `observed_ms` is
   *  how long it could hear the point at all, which is what makes the number a stated lower bound
   *  rather than a claim. `site` is "A" for the single grenade point (F88: a beacon carries no id).
   *  MC merges these by MAX per (site, team) and NEVER by sum — see `scoring._possession`. */
  site?: string;
  hold_ms?: Record<string, number>;
  observed_ms?: number;
  source?: 'beacon' | 'station';
  /** status */
  hp?: number;
  armor?: number;
  ammo?: number;
  alive?: boolean;
  shots?: number;
  deadline_s?: number;
  battery?: number;
  fw?: string;
  arm_state?: ArmState;
  t_minus_ms?: number;
  /** X2: the advert `game` byte (1..255) the phone holds from `config.game_byte`. A fresh MC that adopts an
   *  orphan match takes it (`Session.adopt_orphan`). An older phone omits it. */
  game_byte?: number;
  synced?: boolean;
  dropped?: number;
  /** O6: the phone's drop count for the match it is playing now, scoped at the source (a bounded per-match map in its
   *  storage): {match_id, n}. Sent whenever the phone knows its match, 0 included. */
  outbox_lost?: OutboxLostReport;
  /** O10: a Stick's CLAIM reports evicted from a full queue since it was armed for the game `actions_dropped_game`
   *  (it resets on a new game byte or station; 0 included; `_game` absent while the Stick is not armed). */
  actions_dropped?: number;
  actions_dropped_game?: number;
  preflight?: Preflight;
  /** A37/R2-3: WHERE `hp`/`armor` above came from THIS LIFE. `engine.js` fills them from
   *  `config.health` at spawn/revive -- the phone's MODEL of the pool -- and overwrites them with the
   *  gun's own numbers on the first `$LCD`/`$HP`. The `$PSET` MC pushed bakes
   *  `loadout.overrides.max_hp/max_armor` and the body_armor perk, so the two legitimately disagree
   *  until the gun has spoken, and `state.py _check_pool` judges `"gun"` ONLY. Optional: an app that
   *  omits it makes no claim at all, and the check keeps waiting rather than guessing. */
  pool_src?: 'gun' | 'model';
  /** A36: the `config_id` of the head this node is CURRENTLY holding (`engine.js statusBody`).
   *  `ack_config` says which config a gun took at the moment it took it; this says which one it is
   *  still on, every ~2 s, for the rest of the game -- the difference that made a whole field night
   *  of stale pushes invisible. Optional: an older app omits it and MC then makes no claim. */
  config_id?: string;
  /** F208: the pool this status reports is STALE, and why. A gun that died kept a byte-identical status
   *  for 105 s and looked like a healthy idle player. `"silent"` = no gun frame for 185 s; `"no_fire"` =
   *  three trigger presses in a row got no shot back; `"write_lost"` = this life's spawn or revive write was
   *  lost and the phone did not repeat it (pl4: RESYNC GUN clears it); `"pool_wrong"` = the gun reports pools above (or,
   *  at the spawn read-back, other than) the ones its `$PSET` armed, and two repairs did not hold (F341: FORCE RESPAWN).
   *  `pool_stale_ms` = ms since the gun last reported a
   *  pool. Absent = not stale, or an older app: MC then shows no cue at all. */
  pool_stale?: 'silent' | 'no_fire' | 'write_lost' | 'pool_wrong';
  pool_stale_ms?: number;
  /** F264: what the node ITSELF did about a `pool_stale` claim, so the board reads more than "stale".
   *  `asking` = a $QUERY/$LIFE probe is out; `dead` = the gun answered health 0 and the death is booked;
   *  `alive` = it answered above 0 and the node re-asserted the arming, never a revive; `no_answer` =
   *  nothing came back and the node deliberately did NOTHING. `no_answer` is the one that needs a human. */
  cure?: 'asking' | 'dead' | 'alive' | 'no_answer';
  /** F272: positive lock-up verdict. False/absent is deliberately no claim. */
  gun_locked?: boolean;
  /** F289: true-only while the phone still owes the write that ends spawn protection. Absent = no claim. */
  protected?: boolean;
  /** F309: the phone's own connection (Capacitor Network `connectionType`), restated on every heartbeat.
   *  A CLAIM, unlike `reach` (which MC stamps from the socket): only the phone knows whether it is
   *  riding the field Wi-Fi. Absent = an older app or no answer; MC reads anything unknown as not cellular.
   *  The node says `cellular` only when the network at bind time AND the current one are both cellular
   *  (a bound socket stays on the network it opened on); the full rule is contracts §5d. */
  transport?: 'wifi' | 'cellular' | 'none' | 'unknown';
}

export interface ScoreRow {
  player_id: string;
  display: string;
  team_id: string | null;
  kills: number;
  deaths: number;
  assists: number;
  shots: number;
  hits: number;
  accuracy: number | null;
  kd: number;
  /** CURRENT streak — 0 for whoever died last. `best_streak` is the one to show. */
  streak: number;
  medals: string[];
  /** --- additive, 2026-09-11 (F116 / F119). NotRequired, not merely new: `scoring.py` fills all five on
   *  every LIVE row, but a session PERSISTED before the change replays rows without them, so a reader that
   *  assumes them crashes on last week's recap. Never read one without a fallback. ---
   *  shots incl. the pre-hot-swap baseline (A6.2); == `shots` */
  shots_total?: number;
  /** F116: the LONGEST streak this match. `streak` stayed for compatibility. */
  best_streak?: number;
  /** the longest multi-kill chain (2 double ... 8+ killionaire, types.MEDALS); 0 = none */
  multi_best?: number;
  /** this player drew first blood */
  first_blood?: boolean;
  /** F119: `accuracy` is not settled yet — render it as settling, not as fact */
  acc_provisional?: boolean;
  /** 2026-09-12, the same additive rule as the five above: `scoring.rows()` fills both on every LIVE row
   *  (0 when nothing landed late) and `rows_csv` has a column for each, but a session PERSISTED before
   *  they existed replays rows without them. Kills and deaths scored AFTER the whistle (A6.1 parks them,
   *  they do not move the tally) -- read either one only with a fallback. */
  after_end_kills?: number;
  after_end_deaths?: number;
}

/** A47: the last operator action MC sent to one player, and what the phone said about it.
 *  `state` is "sent" until the phone's `operator_result` fact arrives, then "done" or "refused". With no
 *  answer OPERATOR_NO_ANSWER_MS after the send it reads "no_answer" (an older app, a dropped socket); a late
 *  answer still replaces it. For relink, "done" means the phone STARTED the relink, not that the gun is back. */
export interface OperatorStatus {
  cmd: OperatorCmd;
  state: 'sent' | 'done' | 'refused' | 'no_answer';
  why: string | null;
  sent_t: number;
  result_t: number | null;
}

export interface LiveRow {
  player_id: string;
  display: string;
  team_id: string | null;
  kills: number;
  deaths: number;
  assists: number;
  shots: number;
  hits: number;
  accuracy: number | null;
  kd: number;
  streak: number;
  medals: string[];
  shots_total?: number;
  best_streak?: number;
  multi_best?: number;
  first_blood?: boolean;
  acc_provisional?: boolean;
  after_end_kills?: number;
  after_end_deaths?: number;
  status: 'alive' | 'down' | 'stale';
  sync_age_ms: number;
  respawn_in_s: number | null;
  /** F208: the bound node's `pool_stale` / `pool_stale_ms`, as NodeView. Absent = not stale. */
  pool_stale?: 'silent' | 'no_fire' | 'write_lost' | 'pool_wrong';
  pool_stale_ms?: number;
  /** F264: what the node ITSELF did about a `pool_stale` claim, so the board reads more than "stale".
   *  `asking` = a $QUERY/$LIFE probe is out; `dead` = the gun answered health 0 and the death is booked;
   *  `alive` = it answered above 0 and the node re-asserted the arming, never a revive; `no_answer` =
   *  nothing came back and the node deliberately did NOTHING. `no_answer` is the one that needs a human. */
  cure?: 'asking' | 'dead' | 'alive' | 'no_answer';
  /** F272: the bound node's current positive lock-up verdict. Absent = no claim or an older app. */
  gun_locked?: boolean;
  /** A47: the latest operator action for this player in THIS match. Absent = none sent. */
  operator?: OperatorStatus;
  /** F289: true-only. The row is `stale` and the newest evidence says the phone had not ended spawn
   *  protection, so the gun may still take no damage. Absent = no such claim. */
  possibly_protected?: boolean;
}

