/** A25: one node's log-sync state, as `state.py _set_log()` writes it. Fed ONLY by what the PHONE
 *  reports (`status.log`, `log_offer`, the `log_data` stream) -- MC asking does not make it `offered`.
 *
 *  `state` and `last_t` are written on every call; the other three are carried only when the node said
 *  something about them (`reason` is cleared on every state change, so it never goes stale).
 *  `complete` sticks until something new happens: the phone idles straight back to `none` when it
 *  finishes, and taking that literally would erase the one state the operator is waiting for. */
export interface LogView {
  state: 'none' | 'offered' | 'pulling' | 'held' | 'complete';
  last_t: number;
  /** the node's own words out of `held(2 facts pending)` */
  reason?: string;
  lines?: number;
  bytes?: number;
}

/** One player's row on the readiness board. `state.py readiness()` is the ONLY producer.
 *
 *  NOT `total=False`: `readiness()` builds the row as ONE literal, at the end of the loop body, once
 *  every field it needs (`identity`, `headset`/`headset_proof`, `blockers`/`ambers`, ...) has been
 *  worked out -- so every path through the function writes every key. A reader guarding for a MISSING
 *  key is guarding against nothing, while the fields that really are uncertain arrive as an explicit
 *  `None` and were the ones being read unguarded. What is unknown on this row is the VALUE, never the
 *  key, and `| None` is how that is said. */
export interface ReadinessRow {
  /** "" for a player with no gun assigned */
  gun_id: string;
  /** falls back to the gun_id, then to an em dash */
  sticker: string;
  /** "" when the gun is not in the armory */
  tail: string;
  player_id: string;
  player_num: number;
  /** is a node bound to this player at all */
  present: boolean;
  identity: 'ok' | 'unconfirmed' | 'reverted' | 'unknown' | 'manual';
  node: 'none' | 'linked';
  headset: 'proven' | 'unknown' | 'absent';
  /** A32: HOW the headset was proven, so the UI can say it -- `"echo"` = the gun answered the config
   *  push, `"link"` = a BLE link that has held for HEADSET_LINK_PROOF_MS, `None` = not proven (yet). */
  headset_proof: 'echo' | 'link' | null;
  /** A37: the WEAPON check's own state, and it has THREE answers, not two.
   *  "proven"     -- the gun's slot-0 `$ALCD` carried the magazine the head's `$WEAP,0` wrote;
   *  "mismatch"   -- it carried a different one (the row's red `GUN ECHO ≠ CONFIG` blocker);
   *  "not_echoed" -- the gun answered the head but said nothing about ammo.
   *  The third state exists because it is the NORMAL one in the field: `protocol/brx-protocol.md`
   *  records the `$WEAP` echo as never seen from our v4.32 units and `$ALCD` as streaming on ammo
   *  events only, so the usual answer to a head write is `$START`'s `$LCD,0,0,0,0,0,0,*` and nothing
   *  else. Rendered NEUTRAL (never red, never counted as proven): a green row that ran no weapon
   *  check must be visibly different from one that ran it and passed. `None` = nothing pushed, no
   *  ack yet, the ack is for another head (the stale-ack blocker owns that row), or the head carries
   *  no readable `$WEAP,0` -- in every one of those there is no check to report on. */
  echo: 'proven' | 'mismatch' | 'not_echoed' | null;
  /** Everything below is the NODE's last word, passed through verbatim. `None` = the node has not said
   *  it (or no node is bound): the KEY is always here, the answer may not be. */
  battery_pct: number | null;
  battery_age_ms: number | null;
  /** ms since this node's last packet; None when no node is bound */
  last_seen_age_ms: number | null;
  /** `status.preflight.gun_linked` as last reported */
  gun_linked: boolean | null;
  /** `status.preflight.gun_flapping` (bench 2026-09-17). The card shows one steady HEADSET OFF line while
   *  it is true. An older server omits it, so a reader treats a missing key as false. */
  gun_flapping?: boolean;
  /** F208: `status.pool_stale`; None = not stale or not reported */
  pool_stale: 'silent' | 'no_fire' | 'write_lost' | 'pool_wrong' | null;
  /** F208: `status.pool_stale_ms`; None = not reported */
  pool_stale_ms: number | null;
  /** F264: the node's own outcome; None = it has not acted */
  cure: 'asking' | 'dead' | 'alive' | 'no_answer' | null;
  /** F272: positive verdict only; absent = no claim or older app */
  gun_locked?: boolean;
  fw: string | null;
  phone_batt: number | null;
  ssid_ok: boolean | null;
  mc_reachable: boolean | null;
  /** A28.3, stamped by MC from the socket path; None once the socket is gone */
  reach: 'lan' | 'backhaul' | null;
  /** field 2026-09-12 (F155): outlives the socket so a stale row can say which path it had */
  last_reach: 'lan' | 'backhaul' | null;
  synced: boolean | null;
  screen_on: boolean | null;
  foreground: boolean | null;
  /** A29: the phone's real build, as it reported it (`"0.1.9+abc123"`), and its platform. Rendered on
   *  the row so the operator can read WHICH phone is behind without opening the node list. */
  app_ver: string | null;
  platform: string | null;
  /** A25: the same log view the node card carries, on the per-player board. */
  log: LogView | null;
  /** `waiting` = the phone has not connected yet. Blocks the start exactly like `red`, but it is
   *  not a fault and the UI must not paint it as one (field 2026-09-01). */
  status: 'green' | 'amber' | 'red' | 'waiting';
  /** things that actually gate the start */
  blockers: string[];
  /** advisories -- never gate anything */
  ambers: string[];
}

export interface ReadinessSnapshot {
  t: number;
  roster_size: number;
  greens: number;
  board: ReadinessRow[];
  unclaimed: ScanRow[];
  /** Round-2 fix pass B (2026-09-12): faults about the ROSTER AS A WHOLE rather than any one gun —
   *  today exactly one, "all players on one team", which `push_config` and `start` refuse outright
   *  (`force` included). Each entry is operator-facing copy; a non-empty list forces `go` false. */
  roster_faults: string[];
  /** F-3 (2026-09-13): a connected companion phone with a gun set, claimed by nobody on the roster
   *  and not parked on STANDBY either — never blocks `go`, it is the field's own "4 guns connected,
   *  only 2 in lobby" confusion made visible on KIT/LOBBY (`state.py unrostered_phone_count()`). */
  unrostered_phones: number;
  /** Review finding, 2026-09-19: a friendly, NEVER-blocking heads-up naming every bound node still
   *  below `RESPAWN_PROFILE_MIN_APP` — a mixed fleet plays fine (the 0.4 compat gate is unrelated),
   *  it just keeps the old spawn-protection rules until it updates. `None` when nobody is behind. */
  respawn_rules_warning: string | null;
  go: boolean;
}

/** LAN details attached to every snapshot. Newer fields stay optional for older MC servers. */
export interface LanView {
  mode: 'router' | 'hotspot' | 'lan' | 'unknown';
  ip: string;
  port: number;
  ws_url: string;
  qr: string;
  ssid?: string | null;
  warning?: string | null;
  join_secret?: string;
  public?: LanPublic;
  auth_required?: boolean;
}

export interface KitView {
  kitted: number;
  total: number;
  trying: Record<string, string>;
  browsing: Record<string, number>;
}

export interface GunConfigReadback {
  player_id: number;
  team: number;
  hp: number;
  armor: number;
  shield: number;
}

export interface LobbyAck {
  ok: boolean;
  gun_echo?: string;
  gun_config?: GunConfigReadback;
  err?: string;
  config_id?: string;
}

export interface LobbyView {
  ready: number;
  /** F178: the READY players whose gun has not answered the pushed head yet (a subset of `ready`).
   *  NotRequired: an older server never sends it, and the console reads its absence as 0. */
  updating?: number;
  total: number;
  pushed: boolean;
  acks: Record<string, LobbyAck>;
  all_acked?: boolean;
}

export interface GameAnnouncementView {
  loaded: boolean;
  config_id?: string;
  sent: number;
  total: number;
}

export interface SyncRow {
  player_id: string;
  display: string;
  gun_id: string;
  player_num: number;
  bound: boolean;
  phone_game: boolean;
  gun_sent: boolean;
  gun_acked: boolean;
  gun_echo: 'proven' | 'mismatch' | 'not_echoed' | null;
  ack_state: SyncAckState;
}

export interface SyncTotals {
  rostered: number;
  phone_game: number;
  gun_sent: number;
  gun_acked: number;
  gun_echo_proven: number;
  in_sync: boolean;
}

export interface SyncView {
  rows: SyncRow[];
  totals: SyncTotals;
  unconfigured: string[];
}

export interface SessionOptions {
  log_sync: 'auto' | 'manual';
}

export interface VersionsView {
  field: Record<string, number>;
  newest: string | null;
  release: string | null;
  mc_major: string;
}

export interface NoticesView {
  mc_verify?: string;
}

/** Bench 2026-09-17: phones report ARMED/LIVE in a match this MC did not start. A phone need not be
 *  BOUND to a player for its claim to count here (F261, bench 2026-09-18: a fresh MC has no roster yet).
 *
 *  Absent from `State` unless at least one such phone is heard now. `players` are display names, or the
 *  node id for a phone MC has not bound to a player yet. `can_resume` is false while MC runs or recaps
 *  a match of its own (END THEIR MATCH still works). */
export interface OrphanMatchView {
  match_id: string;
  phones: number;
  players: string[];
  arm_state: 'armed' | 'live';
  can_resume: boolean;
}

export interface RestoredFromView {
  at: number | null;
  players: number;
}

export interface RestoreFailedView {
  reason: string;
  kept: string | null;
}

export interface ArmoryCorruptView {
  kept: string | null;
  error: string;
  /** true: armory.json could not be read at all (transient; the next good read clears it) */
  unreadable?: boolean;
}

export interface FeedEntry {
  id?: number;
  t_match_s: number;
  text: string;
  /** a FeedTagValue, or a kill's medal tag */
  tag?: string;
  kind: 'kill' | 'sync' | 'info' | 'alert';
}

export interface SnapshotFeedRow {
  /** F454: a monotonic row id, so `feed_edit` can replace the row; absent on a row restored from an old snapshot */
  id?: number;
  /** F475: "node:seq:n", the stored fact a scorer row came from; a clock-step rescore re-dates the row by it */
  fact?: string;
  t_match_s: number;
  text: string;
  /** a FeedTagValue, or a kill's medal tag (see FeedTagValue) */
  tag?: string;
  kind: 'kill' | 'sync' | 'info' | 'alert';
}

/** O7/O8: a repeating failure MC counts instead of logging per occurrence. Absent from the snapshot = healthy. */
export interface FailureView {
  /** MC clock ms of the first failure of this streak */
  since: number;
  /** failures in this streak */
  count: number;
  /** the last error's type and text, cut at 200 characters */
  error: string;
}

/** O7: which part of MC's persistence is failing. `store` = facts and log rows (a game result can be lost: RED);
 *  `archive` = the match start / end rows (RED: the game result; cleared only by a later archive write, and an END that
 *  updates 0 rows counts as a failure); `snapshot` = the roster / match file a restart restores (AMBER, RED while a match is in play). */
export interface NotSavingView {
  store?: FailureView;
  archive?: FailureView;
  snapshot?: FailureView;
}

/** O8: the last `join_info()` call raised. `ws_url` is the node URL the QR still holds: "" when none was ever read,
 *  otherwise an EARLIER address that may be out of date. Cleared by the next successful call. */
export interface JoinErrorView {
  error: string;
  ws_url: string;
}

/** One complete Mission Control snapshot (`GET /api/state` and `/ui-ws`). */
export interface State {
  session_id: string;
  phase: Phase;
  t: number;
  lan: LanView;
  mc_confidence: McConfidence;
  nodes: NodeView[];
  readiness: ReadinessSnapshot;
  config: ConfigView;
  config_errors: string[];
  players: Player[];
  teams: Team[];
  kit: KitView;
  loadout_pool: LoadoutPool;
  lobby: LobbyView;
  feed: SnapshotFeedRow[];
  /** Additive fields below are absent from snapshots emitted by older MC versions. Keep these
   *  optional on the client so rolling a new console back to an older server remains safe. */
  coverage?: Coverage;
  stations?: StationView[];
  /** bench 2026-10-02: absent on an older MC */
  station_departures?: StationDeparture[];
  game_byte?: number;
  config_warnings?: string[];
  standby?: Player[];
  /** F411: absent = a server that predates PLAY/BUILD */
  game_pick?: GamePick;
  /** F411: absent until a match has been played */
  last_match?: LastMatch;
  restored_from?: RestoredFromView;
  /** O1: session.json could not be restored; kept aside */
  restore_failed?: RestoreFailedView;
  /** O2: armory.json is corrupt (left in place, backup copy at `kept`); the armory shown is NOT the full one. STICKY: ABSENT only until the operator dismisses it (POST /api/armory/corrupt/dismiss) */
  armory_corrupt?: ArmoryCorruptView;
  game?: GameAnnouncementView;
  sync?: SyncView;
  options?: SessionOptions;
  versions?: VersionsView;
  /** O7: absent = everything MC writes is being kept */
  not_saving?: NotSavingView;
  /** O8: absent = the match tick runs; armed->live / the timed end do not while present */
  ticker_failing?: FailureView;
  /** O8: absent = join_info() worked */
  join_error?: JoinErrorView;
  start?: StartView | null;
  live?: LiveView | null;
  recap?: RecapView | null;
  notices?: NoticesView;
  end_delivery?: EndDeliveryView;
  /** bench 2026-09-17: absent unless phones are in a match MC did not start */
  orphan_match?: OrphanMatchView;
  /** `--bench-volume N`: every $VOL MC compiles plays at N. Absent on a normal run */
  bench_volume?: number;
  /** S50 build 4: {player_id: resolved effect},
   *  one entry per player carrying a perk (absent players carry none;
   *  the whole key absent when nobody on the roster has a perk). The
   *  SAME numbers `FrameBundle.perk_effects` carries for that player --
   *  `Compiler.perk_effects_resolved()` is the one arithmetic both read,
   *  so the console and the node can never disagree. */
  perk_effects?: Record<string, PerkEffectsResolved>;
}

export interface Envelope {
  v: number;
  kind: string;
  id: string;
  seq?: number;
  t: number;
  body: Record<string, unknown>;
}

/** A47: `POST /api/players/{pid}/operator`. `pushed` means only that a socket took the push: no ack
 *  kind exists for `control`, so the phone's own log and the next heartbeat are the receipt. */
export interface OperatorActionResult {
  ok: boolean;
  cmd: OperatorCmd;
  player_id: string;
  match_id: string;
  pushed: boolean;
}

